-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.search_notes_except(query text, max_results integer, excluded_courses text[])
 RETURNS TABLE(note_id text, note_slug text, note_title text, course_name text, anchor text, section text, snippet text, score real)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with q as (select public.query_to_tsquery(query) as tsq)
  select s.note_id,
         n.slug,
         n.title,
         c.name,
         s.anchor,
         s.title,
         ts_headline('public.es'::regconfig, s.body, q.tsq,
                     'StartSel=⟦, StopSel=⟧, MaxWords=30, MinWords=12, MaxFragments=2, FragmentDelimiter=" … "'),
         ts_rank_cd(s.search, q.tsq)
    from q
    join public.note_sections s on s.search @@ q.tsq
    join public.notes n on n.id = s.note_id
    join public.courses c on c.id = n.course_id
   where numnode(q.tsq) > 0
     and not (n.course_id = any (coalesce(excluded_courses, '{}')))
   order by 8 desc, n.position, s.position
   limit least(greatest(coalesce(max_results, 30), 1), 50);
$function$;

grant execute on function public.search_notes_except(query text, max_results integer, excluded_courses text[]) to service_role;
